package org.exist.extensions.exquery.restxq.impl.adapters;

import net.bytebuddy.ByteBuddy;
import net.bytebuddy.dynamic.loading.ClassLoadingStrategy;
import net.bytebuddy.implementation.MethodDelegation;
import net.bytebuddy.implementation.bind.annotation.AllArguments;
import net.bytebuddy.implementation.bind.annotation.Origin;
import net.bytebuddy.implementation.bind.annotation.RuntimeType;
import net.bytebuddy.matcher.ElementMatcher;
import org.exist.dom.persistent.NodeHandle;
import org.exist.dom.persistent.NodeProxy;
import org.exist.xquery.value.Type;
import org.w3c.dom.Attr;
import org.w3c.dom.CDATASection;
import org.w3c.dom.CharacterData;
import org.w3c.dom.Comment;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.ProcessingInstruction;
import org.w3c.dom.Text;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;

import static net.bytebuddy.matcher.ElementMatchers.isDeclaredBy;

/**
 * A NodeProxy Proxy which enhances NodeProxy
 * with a W3C DOM implementation by proxying to
 * its underlying typed node which is available
 * through NodeProxy.getNode()
 *
 * @author <a href="mailto:adam.retter@googlemail.com">Adam Retter</a>
 */
class DomEnhancingNodeProxyAdapter {

    public static NodeProxy create(final NodeProxy nodeProxy) {

        final Class<? extends Node> clazzes[] = getNodeClasses(nodeProxy);

        try {
            return new ByteBuddy()
                    .subclass(NodeProxy.class)
                    .implement(clazzes)
                    .method(isDeclaredByW3cDom())
                    .intercept(MethodDelegation.to(new NodeDispatcher(nodeProxy)))
                    .make()
                    .load(DomEnhancingNodeProxyAdapter.class.getClassLoader(), ClassLoadingStrategy.Default.INJECTION)
                    .getLoaded()
                    .getDeclaredConstructor(NodeHandle.class)
                    .newInstance(nodeProxy);
        } catch (final ReflectiveOperationException e) {
            throw new IllegalStateException("Unable to create DOM-enhancing NodeProxy", e);
        }
    }

    private static ElementMatcher.Junction isDeclaredByW3cDom() {
        return isDeclaredBy(Node.class)
                .or(isDeclaredBy(Document.class))
                .or(isDeclaredBy(Element.class))
                .or(isDeclaredBy(Attr.class))
                .or(isDeclaredBy(CharacterData.class))
                .or(isDeclaredBy(Text.class))
                .or(isDeclaredBy(CDATASection.class))
                .or(isDeclaredBy(Comment.class))
                .or(isDeclaredBy(ProcessingInstruction.class));
    }

    private static Class<? extends Node>[] getNodeClasses(final NodeProxy nodeProxy) {
        switch(nodeProxy.getType()) {

            case Type.DOCUMENT:
                return new Class[] {
                    Document.class,
                    Node.class
                };

            case Type.ELEMENT:
                return new Class[] {
                    Element.class,
                    Node.class
                };

            case Type.ATTRIBUTE:
                return new Class[] {
                    Attr.class,
                    Node.class
                };

            case Type.TEXT:
                return new Class[] {
                    Text.class,
                    Node.class
                };

            case Type.CDATA_SECTION:
                return new Class[] {
                    CDATASection.class,
                    Text.class,
                    Node.class
                };

            case Type.COMMENT:
                return new Class[] {
                    Comment.class,
                    Node.class
                };

            case Type.PROCESSING_INSTRUCTION:
                return new Class[] {
                    ProcessingInstruction.class,
                    Node.class
                };

            default:
                return new Class[] {
                    Node.class
                };
        }
    }

    public static class NodeDispatcher {

        private final NodeProxy nodeProxy;

        public NodeDispatcher(final NodeProxy nodeProxy) {
            this.nodeProxy = nodeProxy;
        }

        @RuntimeType
        public Object dispatch(@Origin final Method method, @AllArguments final Object[] args) throws Throwable {
            try {
                return method.invoke(nodeProxy.getNode(), args);
            } catch (final InvocationTargetException e) {
                throw e.getCause();
            }
        }
    }
}

